function useHashRoute() {
  const parse = () => {
    const h = window.location.hash || "";
    const m = h.match(/^#\/resident\/(.+)$/);
    return m ? decodeURIComponent(m[1]) : null;
  };
  const [apt, setApt] = useState(parse());
  useEffect(() => {
    const onHash = () => setApt(parse());
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);
  return [apt, setApt];
}

function buildResidentLink(apt) {
  const base =
    window.location.origin + window.location.pathname + window.location.search;
  return `${base}#/resident/${encodeURIComponent(apt)}`;
}

function qrImageUrl(link) {
  return `https://api.qrserver.com/v1/create-qr-code/?size=220x220&margin=8&data=${encodeURIComponent(
    link
  )}`;
}

/* ---------------------------- Shell ---------------------------- */

export default function WoningdossierApp() {
  const [residentApt, setResidentApt] = useHashRoute();

  return residentApt ? (
    <ResidentView
      apt={residentApt}
      onBack={() => {
        window.location.hash = "";
        setResidentApt(null);
      }}
    />
  ) : (
    <AdminView
      onPreview={(apt) => {
        window.location.hash = `/resident/${encodeURIComponent(apt)}`;
      }}
    />
  );
}

/* ---------------------------- Admin ---------------------------- */

function AdminView({ onPreview }) {
  const t = T.nl;
  const [loading, setLoading] = useState(true);
  const [project, setProject] = useState(PROJECT_DEFAULT);
  const [sharedDocs, setSharedDocs] = useState(
    Object.fromEntries(SHARED_KEYS.map((k) => [k, ""]))
  );
  const [contact, setContact] = useState(
    Object.fromEntries(CONTACT_KEYS.map((k) => [k, ""]))
  );
  const [apartments, setApartments] = useState([]);
  const [selectedApt, setSelectedApt] = useState(null);
  const [aptDocs, setAptDocs] = useState(
    Object.fromEntries(UNIQUE_KEYS.map((k) => [k, ""]))
  );
  const [newAptNumber, setNewAptNumber] = useState("");
  const [status, setStatus] = useState({});
  const [copiedApt, setCopiedApt] = useState(null);

  const loadAll = useCallback(async () => {
    setLoading(true);
    try {
      const proj = await storage.get("project-info").catch(() => null);
      if (proj?.value) setProject({ ...PROJECT_DEFAULT, ...JSON.parse(proj.value) });
    } catch (e) {}
    try {
      const shared = await storage.get("shared-docs").catch(() => null);
      if (shared?.value) setSharedDocs(JSON.parse(shared.value));
    } catch (e) {}
    try {
      const c = await storage.get("contact-info").catch(() => null);
      if (c?.value) setContact(JSON.parse(c.value));
    } catch (e) {}
    try {
      const list = await storage.list("apt:");
      const keys = (list?.keys || []).map((k) => k.replace(/^apt:/, ""));
      keys.sort((a, b) =>
        a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" })
      );
      setApartments(keys);
    } catch (e) {
      setApartments([]);
    }
    setLoading(false);
  }, []);

  useEffect(() => {
    loadAll();
  }, [loadAll]);

  const saveProject = async () => {
    setStatus((s) => ({ ...s, project: t.saving }));
    try {
      await storage.set("project-info", JSON.stringify(project));
      setStatus((s) => ({ ...s, project: t.saved }));
    } catch (e) {
      setStatus((s) => ({ ...s, project: "" }));
    }
  };

  const saveSharedDocs = async () => {
    setStatus((s) => ({ ...s, shared: t.saving }));
    try {
      await storage.set("shared-docs", JSON.stringify(sharedDocs));
      setStatus((s) => ({ ...s, shared: t.saved }));
    } catch (e) {
      setStatus((s) => ({ ...s, shared: "" }));
    }
  };

  const saveContact = async () => {
    setStatus((s) => ({ ...s, contact: t.saving }));
    try {
      await storage.set("contact-info", JSON.stringify(contact));
      setStatus((s) => ({ ...s, contact: t.saved }));
    } catch (e) {
      setStatus((s) => ({ ...s, contact: "" }));
    }
  };

  const selectApartment = async (apt) => {
    setSelectedApt(apt);
    setStatus((s) => ({ ...s, apt: "" }));
    try {
      const res = await storage.get(`apt:${apt}`).catch(() => null);
      setAptDocs(
        res?.value
          ? { ...Object.fromEntries(UNIQUE_KEYS.map((k) => [k, ""])), ...JSON.parse(res.value) }
          : Object.fromEntries(UNIQUE_KEYS.map((k) => [k, ""]))
      );
    } catch (e) {
      setAptDocs(Object.fromEntries(UNIQUE_KEYS.map((k) => [k, ""])));
    }
  };

  const addApartment = async () => {
    const num = newAptNumber.trim();
    if (!num) return;
    if (!apartments.includes(num)) {
      try {
        await storage.set(
          `apt:${num}`,
          JSON.stringify(Object.fromEntries(UNIQUE_KEYS.map((k) => [k, ""])))
        );
        const next = [...apartments, num].sort((a, b) =>
          a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" })
        );
        setApartments(next);
      } catch (e) {}
    }
    setNewAptNumber("");
    selectApartment(num);
  };

  const saveAptDocs = async () => {
    if (!selectedApt) return;
    setStatus((s) => ({ ...s, apt: t.saving }));
    try {
      await storage.set(`apt:${selectedApt}`, JSON.stringify(aptDocs));
      setStatus((s) => ({ ...s, apt: t.saved }));
    } catch (e) {
      setStatus((s) => ({ ...s, apt: "" }));
    }
  };

  const deleteApartment = async (apt) => {
    if (!window.confirm(t.confirmDelete)) return;
    try {
      await storage.delete(`apt:${apt}`).catch(() => {});
      const next = apartments.filter((a) => a !== apt);
      setApartments(next);
      if (selectedApt === apt) {
        setSelectedApt(null);
        setAptDocs(Object.fromEntries(UNIQUE_KEYS.map((k) => [k, ""])));
      }
    } catch (e) {}
  };

  const copyLink = async (apt) => {
    const link = buildResidentLink(apt);
    try {
      await navigator.clipboard.writeText(link);
      setCopiedApt(apt);
      setTimeout(() => setCopiedApt(null), 1800);
    } catch (e) {
      window.prompt(t.copyLink, link);
    }
  };

  return (
    <div
      style={{
        minHeight: "100%",
        background: BRAND.paper,
        color: BRAND.ink,
        fontFamily: "'Helvetica Neue', Arial, sans-serif",
      }}
    >
      <div
        style={{
          background: "#fff",
          borderBottom: `3px solid ${BRAND.red}`,
          padding: "14px 24px",
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
            flexWrap: "wrap",
            gap: 12,
            maxWidth: 980,
            margin: "0 auto",
          }}
        >
          <img src={LOGO_DATA_URI} alt="Van Wijnen" style={{ height: 26, display: "block" }} />
          <div
            style={{
              fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
              fontSize: 12,
              color: BRAND.mute,
            }}
          >
            {t.adminTitle} · QR-woningdossier
          </div>
        </div>
      </div>

      <div style={{ maxWidth: 980, margin: "0 auto", padding: "28px 24px 64px" }}>
        <section style={{ marginBottom: 32 }}>
          <div
            style={{
              display: "grid",
              gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))",
              gap: 1,
              background: BRAND.line,
              border: `1px solid ${BRAND.line}`,
            }}
          >
            <ProjectField label={t.project} value={project.name} onChange={(v) => setProject({ ...project, name: v })} />
            <ProjectField label={t.projectCode} value={project.code} mono onChange={(v) => setProject({ ...project, code: v })} />
            <ProjectField label={t.tcl} value={project.tcl} mono onChange={(v) => setProject({ ...project, tcl: v })} />
            <ProjectField label={t.projectNumber} value={project.number} mono onChange={(v) => setProject({ ...project, number: v })} />
          </div>
          <div style={{ marginTop: 10, display: "flex", alignItems: "center", gap: 10 }}>
            <SaveButton onClick={saveProject} label={t.save} />
            {status.project && <span style={{ fontSize: 13, color: BRAND.mute }}>{status.project}</span>}
          </div>
        </section>

        {loading ? (
          <p style={{ color: BRAND.mute }}>{t.loading}</p>
        ) : (
          <>
            <SectionCard title={t.sharedSectionTitle} body={t.sharedSectionBody}>
              {SHARED_KEYS.map((key) => (
                <LinkRow
                  key={key}
                  label={t.docs[key]}
                  value={sharedDocs[key] || ""}
                  placeholder={t.driveLinkPlaceholder}
                  onChange={(v) => setSharedDocs({ ...sharedDocs, [key]: v })}
                />
              ))}
              <div style={{ marginTop: 14, display: "flex", alignItems: "center", gap: 10 }}>
                <SaveButton onClick={saveSharedDocs} label={t.save} />
                {status.shared && <span style={{ fontSize: 13, color: BRAND.mute }}>{status.shared}</span>}
              </div>
            </SectionCard>

            <SectionCard title={t.contactSectionTitle} body={t.contactSectionBody}>
              <LinkRow label={t.contactNameLabel} value={contact.contactName || ""} placeholder="bijv. Herman" onChange={(v) => setContact({ ...contact, contactName: v })} />
              <LinkRow label={t.contactRoleLabel} value={contact.contactRole || ""} placeholder="bijv. Assistent-uitvoerder" onChange={(v) => setContact({ ...contact, contactRole: v })} />
              <LinkRow label={t.contactCompanyLabel} value={contact.contactCompany || ""} placeholder="bijv. Van Wijnen" onChange={(v) => setContact({ ...contact, contactCompany: v })} />
              <LinkRow label={t.contactPhoneLabel} value={contact.contactPhone || ""} placeholder="bijv. 06-12345678" onChange={(v) => setContact({ ...contact, contactPhone: v })} />
              <div style={{ marginTop: 14, display: "flex", alignItems: "center", gap: 10 }}>
                <SaveButton onClick={saveContact} label={t.save} />
                {status.contact && <span style={{ fontSize: 13, color: BRAND.mute }}>{status.contact}</span>}
              </div>
            </SectionCard>

            <SectionCard title={t.apartmentsSectionTitle}>
              <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap" }}>
                <input
                  value={newAptNumber}
                  onChange={(e) => setNewAptNumber(e.target.value)}
                  placeholder={t.newApartment}
                  onKeyDown={(e) => e.key === "Enter" && addApartment()}
                  style={inputStyle}
                />
                <button onClick={addApartment} style={primaryBtnStyle}>{t.addApartment}</button>
              </div>

              {apartments.length === 0 ? (
                <p style={{ color: BRAND.mute, fontSize: 14 }}>{t.noApartments}</p>
              ) : (
                <div style={{ display: "flex", flexWrap: "wrap", gap: 8, marginBottom: 20 }}>
                  {apartments.map((apt) => (
                    <button
                      key={apt}
                      onClick={() => selectApartment(apt)}
                      style={{
                        ...chipStyle,
                        borderColor: selectedApt === apt ? BRAND.red : BRAND.line,
                        background: selectedApt === apt ? "#FCEBEE" : "#fff",
                        color: selectedApt === apt ? BRAND.redDark : BRAND.ink,
                        fontWeight: selectedApt === apt ? 700 : 500,
                      }}
                    >
                      {t.apartmentLabel} {apt}
                    </button>
                  ))}
                </div>
              )}

              {selectedApt && (
                <div style={{ borderTop: `1px solid ${BRAND.line}`, paddingTop: 18 }}>
                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 10 }}>
                    <h4 style={{ margin: 0, fontSize: 15, fontWeight: 700 }}>
                      {t.uniqueDocsTitle} — {t.apartmentLabel} {selectedApt}
                    </h4>
                    <button onClick={() => deleteApartment(selectedApt)} style={dangerLinkStyle}>{t.deleteApartment}</button>
                  </div>

                  {UNIQUE_KEYS.map((key) => (
                    <LinkRow
                      key={key}
                      label={t.docs[key]}
                      value={aptDocs[key] || ""}
                      placeholder={t.driveLinkPlaceholder}
                      onChange={(v) => setAptDocs({ ...aptDocs, [key]: v })}
                    />
                  ))}

                  <div style={{ marginTop: 14, display: "flex", alignItems: "center", gap: 10, flexWrap: "wrap" }}>
                    <SaveButton onClick={saveAptDocs} label={t.save} />
                    {status.apt && <span style={{ fontSize: 13, color: BRAND.mute }}>{status.apt}</span>}
                  </div>

                  <div
                    style={{
                      marginTop: 24,
                      display: "flex",
                      gap: 20,
                      alignItems: "flex-start",
                      flexWrap: "wrap",
                      background: BRAND.panel,
                      borderRadius: 14,
                      padding: 18,
                    }}
                  >
                    <img
                      src={qrImageUrl(buildResidentLink(selectedApt))}
                      alt={`QR ${selectedApt}`}
                      width={140}
                      height={140}
                      style={{ background: "#fff", border: `1px solid ${BRAND.line}`, borderRadius: 10, padding: 6 }}
                    />
                    <div style={{ flex: 1, minWidth: 200 }}>
                      <div style={{ fontWeight: 700, fontSize: 14, marginBottom: 4 }}>{t.qrTitle}</div>
                      <p style={{ fontSize: 13, color: BRAND.mute, margin: "0 0 12px" }}>{t.qrBody}</p>
                      <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
                        <button onClick={() => copyLink(selectedApt)} style={secondaryBtnStyle}>
                          {copiedApt === selectedApt ? t.linkCopied : t.copyLink}
                        </button>
                        <button onClick={() => onPreview(selectedApt)} style={secondaryBtnStyle}>{t.previewAsResident}</button>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </SectionCard>
          </>
        )}
      </div>
    </div>
  );
}

function ProjectField({ label, value, onChange, mono }) {
  return (
    <div style={{ background: "#fff", padding: "12px 14px" }}>
      <div style={{ fontSize: 11, color: BRAND.mute, marginBottom: 4, fontWeight: 600 }}>{label}</div>
      <input
        value={value}
        onChange={(e) => onChange(e.target.value)}
        style={{
          border: "none",
          outline: "none",
          width: "100%",
          fontSize: 15,
          fontWeight: 600,
          color: BRAND.ink,
          fontFamily: mono ? "ui-monospace, SFMono-Regular, Menlo, monospace" : "inherit",
          background: "transparent",
        }}
      />
    </div>
  );
}

function SectionCard({ title, body, children }) {
  return (
    <section style={{ background: "#fff", borderRadius: 14, boxShadow: "0 1px 3px rgba(27,27,24,0.08)", padding: 22, marginBottom: 24 }}>
      <h3 style={{ margin: "0 0 4px", fontSize: 17, fontWeight: 700 }}>{title}</h3>
      {body && <p style={{ margin: "0 0 16px", fontSize: 13.5, color: BRAND.mute, maxWidth: 560 }}>{body}</p>}
      {children}
    </section>
  );
}

function LinkRow({ label, value, onChange, placeholder }) {
  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "180px 1fr",
        gap: 12,
        alignItems: "center",
        padding: "9px 0",
        borderBottom: `1px solid ${BRAND.panel}`,
      }}
    >
      <label style={{ fontSize: 13.5, fontWeight: 600, color: BRAND.ink }}>{label}</label>
      <input value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} style={inputStyle} />
    </div>
  );
}

const inputStyle = {
  border: `1px solid ${BRAND.line}`,
  borderRadius: 8,
  padding: "8px 10px",
  fontSize: 13.5,
  color: BRAND.ink,
  outline: "none",
  minWidth: 160,
  flex: 1,
  fontFamily: "inherit",
};

const primaryBtnStyle = {
  background: BRAND.red,
  color: "#fff",
  border: "none",
  borderRadius: 8,
  padding: "8px 16px",
  fontSize: 13.5,
  fontWeight: 700,
  cursor: "pointer",
};

const secondaryBtnStyle = {
  background: "#fff",
  color: BRAND.ink,
  border: `1px solid ${BRAND.ink}`,
  borderRadius: 8,
  padding: "7px 14px",
  fontSize: 13,
  fontWeight: 600,
  cursor: "pointer",
};

const dangerLinkStyle = {
  background: "none",
  border: "none",
  color: BRAND.mute,
  fontSize: 12.5,
  textDecoration: "underline",
  cursor: "pointer",
  padding: 0,
};

const chipStyle = {
  border: "1px solid",
  borderRadius: 20,
  padding: "7px 14px",
  fontSize: 13.5,
  cursor: "pointer",
  background: "#fff",
};

function SaveButton({ onClick, label }) {
  return <button onClick={onClick} style={primaryBtnStyle}>{label}</button>;
}

/* -------------------------- Icons -------------------------- */

function Icon({ type, color }) {
  const common = { width: 20, height: 20, viewBox: "0 0 24 24", fill: "none", stroke: color, strokeWidth: 1.8, strokeLinecap: "round", strokeLinejoin: "round" };
  if (type === "doc") {
    return (
      <svg {...common}><path d="M7 3h7l4 4v14a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1z" /><path d="M14 3v4h4" /><path d="M9 12h6M9 16h6" /></svg>
    );
  }
  if (type === "ruler") {
    return (
      <svg {...common}><path d="M4 16 16 4l4 4L8 20z" /><path d="M9 11l2 2M12 8l2 2M15 5l2 2" /></svg>
    );
  }
  if (type === "form") {
    return (
      <svg {...common}><path d="M4 20l1.5-4.5L16 5l3 3-10.5 10.5z" /><path d="M14 7l3 3" /></svg>
    );
  }
  if (type === "warning") {
    return (
      <svg {...common}><path d="M12 3 2 20h20z" /><path d="M12 10v4" /><circle cx="12" cy="17" r="0.6" fill={color} stroke="none" /></svg>
    );
  }
  if (type === "person") {
    return (
      <svg {...common}><circle cx="12" cy="8" r="4" /><path d="M4 21c1.5-4 5-6 8-6s6.5 2 8 6" /></svg>
    );
  }
  return null;
}

/* -------------------------- Resident -------------------------- */

function ResidentView({ apt, onBack }) {
  const [lang, setLang] = useState("nl");
  const t = T[lang];
  const [loading, setLoading] = useState(true);
  const [found, setFound] = useState(false);
  const [project, setProject] = useState(PROJECT_DEFAULT);
  const [sharedDocs, setSharedDocs] = useState({});
  const [aptDocs, setAptDocs] = useState({});
  const [contact, setContact] = useState({});

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      try {
        const proj = await storage.get("project-info").catch(() => null);
        if (!cancelled && proj?.value) setProject({ ...PROJECT_DEFAULT, ...JSON.parse(proj.value) });
      } catch (e) {}
      try {
        const shared = await storage.get("shared-docs").catch(() => null);
        if (!cancelled && shared?.value) setSharedDocs(JSON.parse(shared.value));
      } catch (e) {}
      try {
        const c = await storage.get("contact-info").catch(() => null);
        if (!cancelled && c?.value) setContact(JSON.parse(c.value));
      } catch (e) {}
      try {
        const res = await storage.get(`apt:${apt}`).catch(() => null);
        if (!cancelled) {
          if (res?.value) {
            setAptDocs(JSON.parse(res.value));
            setFound(true);
          } else {
            setFound(false);
          }
        }
      } catch (e) {
        if (!cancelled) setFound(false);
      }
      if (!cancelled) setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [apt]);

  const allDocs = { ...sharedDocs, ...aptDocs };
  const hasContact = contact.contactName || contact.contactPhone;

  const docTitle = (d) => {
    const base = t.docs[d.key];
    if (d.withCode) return `${base} ${project.code} ${apt}`;
    return base;
  };

  return (
    <div style={{ minHeight: "100%", background: BRAND.paper, color: BRAND.ink, fontFamily: "'Helvetica Neue', Arial, sans-serif" }}>
      <div style={{ padding: "14px 20px 0", maxWidth: 640, margin: "0 auto" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", flexWrap: "wrap", gap: 10 }}>
          <img src={LOGO_DATA_URI} alt="Van Wijnen" style={{ height: 22, display: "block" }} />
          <span style={{ fontSize: 12.5, color: BRAND.mute }}>{t.residentEyebrow}</span>
        </div>
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 6, marginTop: 10 }}>
          {["nl", "en", "pl"].map((code) => (
            <button
              key={code}
              onClick={() => setLang(code)}
              style={{
                border: `1px solid ${lang === code ? BRAND.red : BRAND.line}`,
                background: lang === code ? BRAND.red : "#fff",
                color: lang === code ? "#fff" : BRAND.ink,
                fontSize: 11.5,
                fontWeight: 700,
                padding: "5px 12px",
                borderRadius: 20,
                cursor: "pointer",
                textTransform: "uppercase",
              }}
            >
              {code}
            </button>
          ))}
        </div>
      </div>

      <div style={{ background: BRAND.red, marginTop: 14, padding: "22px 20px" }}>
        <div style={{ maxWidth: 640, margin: "0 auto" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 12, color: "#F6C9CF", fontWeight: 700, marginBottom: 6 }}>
            <Icon type="doc" color="#F6C9CF" />
            {t.residentTitle.toUpperCase()}
          </div>
          <h1 style={{ margin: 0, fontSize: 26, fontWeight: 800, color: "#fff" }}>{project.name}</h1>
          <div style={{ fontSize: 14, color: "#F8D3D8", marginTop: 4 }}>{t.tagline}</div>
          <div style={{ display: "flex", gap: 8, marginTop: 14, flexWrap: "wrap" }}>
            <span style={{ background: "rgba(0,0,0,0.18)", color: "#fff", fontSize: 12, fontWeight: 700, padding: "5px 12px", borderRadius: 20, fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace" }}>
              {project.tcl}
            </span>
            <span style={{ background: "rgba(0,0,0,0.18)", color: "#fff", fontSize: 12, fontWeight: 700, padding: "5px 12px", borderRadius: 20, fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace" }}>
              {project.number}
            </span>
          </div>
        </div>
      </div>

      <div style={{ maxWidth: 640, margin: "0 auto", padding: "20px 20px 60px" }}>
        {loading ? (
          <p style={{ color: BRAND.mute }}>{t.loading}</p>
        ) : !found ? (
          <div style={{ borderRadius: 14, boxShadow: "0 1px 3px rgba(27,27,24,0.08)", background: "#fff", padding: 24 }}>
            <h3 style={{ margin: "0 0 8px", fontSize: 16 }}>{t.notFoundTitle}</h3>
            <p style={{ margin: 0, fontSize: 14, color: BRAND.mute }}>{t.notFoundBody}</p>
          </div>
        ) : (
          <div>
            {CATEGORY_ORDER.filter((c) => c !== "contact").map((catKey) => {
              const meta = CATEGORY_META[catKey];
              return (
                <div key={catKey} style={{ marginBottom: 26 }}>
                  <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
                    <span style={{ width: 18, height: 3, background: meta.bar, display: "inline-block" }} />
                    <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: "0.04em", color: BRAND.ink }}>
                      {t.categories[catKey].toUpperCase()}
                    </span>
                  </div>
                  {CATEGORY_DOCS[catKey].map((d) => {
                    const link = allDocs[d.key];
                    return (
                      <a
                        key={d.key}
                        href={link || undefined}
                        target="_blank"
                        rel="noopener noreferrer"
                        style={{
                          display: "flex",
                          alignItems: "center",
                          gap: 14,
                          background: "#fff",
                          borderRadius: 14,
                          boxShadow: "0 1px 3px rgba(27,27,24,0.08), 0 1px 2px rgba(27,27,24,0.04)",
                          padding: "14px 16px",
                          marginBottom: 10,
                          textDecoration: "none",
                          color: "inherit",
                          cursor: link ? "pointer" : "default",
                          opacity: link ? 1 : 0.6,
                        }}
                        onClick={(e) => {
                          if (!link) e.preventDefault();
                        }}
                      >
                        <span
                          style={{
                            width: 40,
                            height: 40,
                            borderRadius: 10,
                            background: meta.iconBg,
                            display: "flex",
                            alignItems: "center",
                            justifyContent: "center",
                            flexShrink: 0,
                          }}
                        >
                          <Icon type={meta.icon} color={meta.iconColor} />
                        </span>
                        <span style={{ flex: 1, minWidth: 0 }}>
                          <div style={{ fontSize: 14.5, fontWeight: 700, color: BRAND.ink }}>{docTitle(d)}</div>
                          <div style={{ fontSize: 12.5, color: BRAND.mute, marginTop: 2 }}>
                            {link ? `${t.tapToOpen} →` : t.unavailable}
                          </div>
                        </span>
                        {link && (
                          <span style={{ color: BRAND.mute, fontSize: 16, flexShrink: 0 }}>→</span>
                        )}
                      </a>
                    );
                  })}
                </div>
              );
            })}

            {hasContact && (
              <div>
                <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 10 }}>
                  <span style={{ width: 18, height: 3, background: CATEGORY_META.contact.bar, display: "inline-block" }} />
                  <span style={{ fontSize: 12, fontWeight: 700, letterSpacing: "0.04em", color: BRAND.ink }}>
                    {t.categories.contact.toUpperCase()}
                  </span>
                </div>
                <a
                  href={contact.contactPhone ? `tel:${contact.contactPhone.replace(/[^+\d]/g, "")}` : undefined}
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 14,
                    background: "#fff",
                    borderRadius: 14,
                    boxShadow: "0 1px 3px rgba(27,27,24,0.08), 0 1px 2px rgba(27,27,24,0.04)",
                    padding: "14px 16px",
                    textDecoration: "none",
                    color: "inherit",
                  }}
                >
                  <span
                    style={{
                      width: 40,
                      height: 40,
                      borderRadius: "50%",
                      background: CATEGORY_META.contact.iconBg,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      flexShrink: 0,
                    }}
                  >
                    <Icon type="person" color={CATEGORY_META.contact.iconColor} />
                  </span>
                  <span style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 14.5, fontWeight: 700, color: BRAND.ink }}>{contact.contactName}</div>
                    <div style={{ fontSize: 12.5, color: BRAND.mute, marginTop: 2 }}>
                      {[contact.contactRole, contact.contactCompany].filter(Boolean).join(" · ")}
                    </div>
                  </span>
                  {contact.contactPhone && (
                    <span style={{ color: BRAND.red, fontWeight: 800, fontSize: 14, flexShrink: 0 }}>
                      {contact.contactPhone}
                    </span>
                  )}
                </a>
              </div>
            )}
          </div>
        )}

        <button
          onClick={onBack}
          style={{ marginTop: 28, background: "none", border: "none", color: BRAND.mute, fontSize: 12.5, textDecoration: "underline", cursor: "pointer", padding: 0 }}
        >
          {t.backToAdmin}
        </button>
      </div>
    </div>
  );
}
